contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        address first = _tos[0];
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        (bool beforeOk, bytes memory beforeRet) = caddress.staticcall(abi.encodeWithSelector(id, from, first, v));
        uint256 beforeBalance = address(caddress).balance;

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address[] memory single = new address[](1);
        single[0] = first;

        bool afterOk;
        bytes memory afterRet;

        if (!reverted) {
            (afterOk, afterRet) = caddress.staticcall(abi.encodeWithSelector(id, from, first, v));
        }

        assert(
            reverted ||
            (!reverted && afterOk && keccak256(afterRet) == keccak256(beforeRet))
        );
    }
}

