contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address from, address caddress, address[] memory _tos, uint v, uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeBal = caddress.balance;

        bool reverted;
        try c.transfer{value: amount}(from, caddress, _tos, v) returns (bool ok) {
            reverted = false;
            assert(ok == true);
            assert(caddress.balance == beforeBal + amount);
        } catch {
            reverted = true;
            assert(caddress.balance == beforeBal);
        }
        assert(reverted == (caddress.balance != beforeBal + amount));
    }
}

